// ForceMode.Force (default): fuerza continua que tiene en cuenta la masa
// F = masa × aceleración → más masa = menos aceleración
rb.AddForce(Vector3.forward * 10f, ForceMode.Force);

// ForceMode.Impulse: fuerza instantánea que tiene en cuenta la masa
// Ideal para saltos, explosiones, disparos
rb.AddForce(Vector3.up * 500f, ForceMode.Impulse);

// ForceMode.Acceleration: fuerza continua IGNORANDO la masa
// Produce la misma aceleración sin importar el peso del objeto
rb.AddForce(Vector3.forward * 5f, ForceMode.Acceleration);

// ForceMode.VelocityChange: cambio instantáneo IGNORANDO la masa
// Establece directamente un incremento de velocidad
rb.AddForce(Vector3.up * 5f, ForceMode.VelocityChange);

